package com.opensocket.aievent.core.iam.api.response;import com.opensocket.aievent.core.iam.organization.domain.Group;import java.time.Instant;
public record GroupResponse(String tenantId,String groupId,String code,String name,String type,String parentGroupId,String ownerDepartmentId,String status,String description,Instant createdAt,Instant updatedAt,long version){public static GroupResponse from(Group g){return new GroupResponse(g.tenantId().value(),g.groupId().value(),g.code(),g.name(),g.type().name(),g.parentGroupId().map(x->x.value()).orElse(""),g.ownerDepartmentId().map(x->x.value()).orElse(""),g.status().name(),g.description(),g.createdAt(),g.updatedAt(),g.version());}}
